#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

REPO="${REPO:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}"   # this checkout
HOST_BIN="$REPO/apps/cli/dist/warden"   # this checkout's warden, compiled for this Mac's arch
LABEL="wizard-ssh"

# run "what" cmd… shows the command, asks y/N, runs it with live output. A failure
# or a "no" is recorded for the closing summary instead of ending the wizard.
run() {
  local desc="$1"; shift
  printf '  %s$%s %s\n' "$DIM" "$RESET" "$*"
  if confirm "Run: $desc?"; then
    if "$@"; then printf '  %s✓ %s%s\n' "$GREEN" "$desc" "$RESET"
    else warn "$desc failed (exit $?)"; SKIPPED+=("$desc: failed, see output above"); fi
  else
    SKIPPED+=("$desc: skipped")
  fi
}

# other_terminal "cmd" puts a long-running command on the clipboard for a
# second terminal: Ctrl-C there must not kill this wizard.
other_terminal() {
  printf '\n    %s%s%s\n\n' "$BOLD" "$1" "$RESET"
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy; note "(copied to clipboard)"; fi
}

# host_lease_id: the wizard's host lease. Another terminal is another owner (the
# shell that claimed owns the lease), so it is named by id there.
host_lease_id() {
  warden ls --json 2>/dev/null | WANT="$LABEL" bun -e '
    const j = await Bun.stdin.json();
    const l = (j.leases ?? []).find((l) => l.resource?.kind === "host-device" && l.label === process.env.WANT);
    console.log(l?.id ?? "");' 2>/dev/null || true
}

# ssh_opts: the plain-ssh flags for the setup key and proxy the user gave.
ssh_opts() {
  SSH_OPTS=()
  [[ -n "${SSH_PORT:-}" ]] && SSH_OPTS+=(-p "$SSH_PORT")
  [[ -n "${SETUP_IDENTITY:-}" ]] && SSH_OPTS+=(-i "$SETUP_IDENTITY")
  [[ -n "${PROXY_COMMAND:-}" ]] && SSH_OPTS+=(-o "ProxyCommand=$PROXY_COMMAND")
  return 0
}

run_wizard() {

TOTAL_STAGES=11
ENV_FILE="$REPO/.env.wizard-ssh-host"   # gitignored (.env.*)
cd "$REPO"

banner "Self-hosted sims over ssh"
say "Drive the sims of another Mac you own (desk Mac, Mac mini, EC2 Mac) from this one."
say "No warden account, no cloud: plain ssh, the other Mac's own warden and sims."

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Laptop: install + link this checkout's warden"
say "Branch: $(git branch --show-current) @ $(git rev-parse --short HEAD)"
[[ -n "$(git status --porcelain)" ]] && warn "worktree has local changes"
run "bun install" bun install
run "link warden (~/.local/bin/warden → this checkout)" bun run cli:link
note "warden now → $(command -v warden || echo 'not on PATH: add ~/.local/bin')"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Host Mac: get it ready (on the other Mac)"
step "Xcode installed and opened once (licence accepted), with an iOS simulator runtime."
step "System Settings → General → Sharing → Remote Login: ON (for your user)."
step "Same chip family as this Mac ($(uname -m)): stage 4 sends a binary built here."
step "Reachable from here: same LAN, Tailscale, or a bastion / proxy command."
pause "Host Mac ready? Press Enter"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "ssh: reach the host with your normal key"
ask SSH_TARGET "ssh target, user@host (e.g. chris@mac-mini.tail1234.ts.net):"
write_env SSH_TARGET "$SSH_TARGET"
ask SSH_PORT "ssh port [22]:"
write_env SSH_PORT "$SSH_PORT"
ask SETUP_IDENTITY "Key that opens a shell there [your ssh default, Enter to skip]:"
write_env SETUP_IDENTITY "$SETUP_IDENTITY"
ask PROXY_COMMAND "Proxy command, e.g. 'tailscale nc %h %p' [none, Enter to skip]:"
write_env PROXY_COMMAND "$PROXY_COMMAND"
ask HOST_NAME "Name for this host in warden [mini]:"
HOST_NAME="${HOST_NAME:-mini}"
write_env HOST_NAME "$HOST_NAME"
ssh_opts
note "No key on the host yet? ssh-copy-id ${SSH_OPTS[*]} $SSH_TARGET (asks the password once)."
run "plain ssh login (accept the host key if asked)" ssh "${SSH_OPTS[@]}" "$SSH_TARGET" 'echo "ok: $(hostname) $(uname -m) $(sw_vers -productVersion)"; xcrun simctl help >/dev/null && echo "simctl: ok"'
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Build the warden the host will run"
say "The host must run the same warden version as this laptop (else HOST_VERSION_SKEW)."
say "So we compile this checkout: $HOST_BIN"
run "build warden binary" bun run --cwd apps/cli build
[[ -x "$HOST_BIN" ]] && note "$("$HOST_BIN" --version 2>/dev/null || echo built)"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Register the host (warden host add)"
say "Pins the host key in ~/.warden/hosts/$HOST_NAME.known_hosts on first contact."
ADD=(warden host add "$HOST_NAME" --ssh "$SSH_TARGET${SSH_PORT:+:$SSH_PORT}")
[[ -n "$SETUP_IDENTITY" ]] && ADD+=(--identity "$SETUP_IDENTITY")
[[ -n "$PROXY_COMMAND" ]] && ADD+=(--proxy-command "$PROXY_COMMAND")
warden host rm "$HOST_NAME" >/dev/null 2>&1 || true   # re-runs start clean
run "host add $HOST_NAME" "${ADD[@]}"
note "'warden: command not found' on the host is expected here: stage 6 installs it."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Install warden on the host + grant this laptop (warden host setup)"
say "Over your normal key: copies the binary to ~/.local/bin/warden there,"
say "fetches the sim helper, then grants this laptop's warden key (forced command,"
say "allowlisted warden calls only). From then on warden uses that key, not yours."
SETUP=(warden host setup "$HOST_NAME" --binary "$HOST_BIN")
[[ -n "$SETUP_IDENTITY" ]] && SETUP+=(--setup-identity "$SETUP_IDENTITY")
if confirm "Also build the golden sim image there (--golden, slow first time)?"; then SETUP+=(--golden); fi
run "host setup $HOST_NAME" "${SETUP[@]}"
run "host doctor (reachable, key, version, leases)" warden host doctor "$HOST_NAME"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Claim a sim on the host"
say "The host's warden picks, boots and leases the sim. A keepalive renews it from here."
run "claim ios --host $HOST_NAME" warden claim ios --host "$HOST_NAME" --label "$LABEL" --ttl 30m
run "list host leases" warden ls --hosts
run "the host's capacity + boot queue" warden --host "$HOST_NAME" capacity
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Drive it with warden ui (every call crosses ssh)"
run "open Settings" warden ui open com.apple.Preferences
run "snapshot (interactive elements)" warden ui snapshot -i
step "Try: warden ui press <ref> from that snapshot, then warden ui snapshot -i again."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Watch + drive it in the browser (warden view)"
LEASE_ID=$(host_lease_id)
[[ -z "$LEASE_ID" ]] && LEASE_ID="<leaseId from: warden ls --hosts>"
step "In a SECOND terminal run this (another terminal = another owner, so by id)."
step "It opens a browser tab on 127.0.0.1:"
other_terminal "warden view $LEASE_ID"
step "Click = tap, drag = swipe, typing types, Esc = home. Portrait only."
step "Ctrl-C there when done (the lease stays yours)."
pause "Done with the browser view? Press Enter"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Dev client on the host, Metro here (optional)"
say "Builds the example app's dev client on first run (can take 10+ min),"
say "installs it on the host's sim and forwards Metro over ssh -R."
note "The host's sshd must allow TCP forwarding (macOS Remote Login does by default)."
if confirm "Try warden dev --host with apps/example?"; then
  step "In the SECOND terminal (stop 'warden view' first) run:"
  other_terminal "cd $REPO/apps/example && warden dev ios --host $HOST_NAME"
  step "Wait for the app on the host's sim, edit a screen in apps/example, watch it refresh."
  step "Ctrl-C there when done: it releases its own leases here and on the host."
  pause "Done with dev --host? Press Enter"
else
  SKIPPED+=("dev --host: skipped")
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Release + clean up"
run "release the wizard's host leases" warden release --mine --label "$LABEL"
run "host doctor (no leases left)" warden host doctor "$HOST_NAME"
if confirm "Remove the '$HOST_NAME' host from this laptop (host rm)?"; then
  run "host rm $HOST_NAME" warden host rm "$HOST_NAME"
  note "The grant stays on the host: there, 'warden host grants' then 'warden host revoke --key SHA256:…'."
fi
pause

finish
note "Answers saved in $ENV_FILE (re-run picks them up)."
note "Back to your normal warden: bun run cli:unlink"
}

run_wizard "$@"; exit
